def toda_pi4_3_delta_image_free_cyclic_inference_rule():
  def guard(
    premises,
    bindings,
  ):
    source_group_relation = (
      premises[
        0
      ].conclusion
    )

    delta_image = (
      premises[
        1
      ].conclusion
    )

    whitehead_square = (
      premises[
        2
      ].conclusion
    )

    expected_source = TodaPrimaryGroup(
      group_dimension=5,
      sphere_dimension=5,
    )

    expected_target = TodaPrimaryGroup(
      group_dimension=3,
      sphere_dimension=2,
    )

    if (
      source_group_relation.lhs
      != expected_source
    ):
      return False

    if not isinstance(
      source_group_relation.rhs,
      FreeCyclicGroup,
    ):
      return False

    iota_5 = HomotopyElement(
      name="ι_5",
      dimension=5,
      generator=GeneratorSymbol(
        family="ι",
        index=5,
      ),
    )

    if (
      source_group_relation.rhs.generator
      != iota_5
    ):
      return False

    if (
      delta_image.map.source_group
      != expected_source
    ):
      return False

    if (
      delta_image.map.target_group
      != expected_target
    ):
      return False

    if (
      delta_image.element
      != iota_5
    ):
      return False

    if (
      delta_image.positive_value
      != whitehead_square.whitehead_square
    ):
      return False

    eta_2 = HomotopyElement(
      name="η₂",
      dimension=2,
      source=3,
      target=2,
      generator=GeneratorSymbol(
        family="η",
        index=2,
      ),
    )

    expected_two_eta_2 = Multiple(
      coefficient=2,
      expression=eta_2,
    )

    return (
      whitehead_square.positive_value
      == expected_two_eta_2
    )

  def build_conclusion(
    premises,
  ):
    delta_image = (
      premises[
        1
      ].conclusion
    )

    whitehead_square = (
      premises[
        2
      ].conclusion
    )

    return (
      TodaDeltaImageFreeCyclicStatement(
        map=delta_image.map,
        image_group=FreeCyclicGroup(
          generator=(
            whitehead_square
            .positive_value
          ),
        ),
      )
    )

  return InferenceRule(
    name=(
      "Toda pi_4^3 Delta image "
      "generated by twice eta_2"
    ),
    description=(
      "If pi_5^5 is freely generated "
      "by iota_5, Delta(iota_5) equals "
      "the Whitehead square up to sign, "
      "and that Whitehead square equals "
      "twice eta_2 up to sign, then the "
      "image of the specific Delta map "
      "is freely generated by 2 eta_2."
    ),
    premise_patterns=(
      PremisePattern(
        statement_type=Relation,
        relation_type=(
          RelationType.EQUALITY
        ),
      ),
      PremisePattern(
        statement_type=(
          TodaDeltaImageUpToSignStatement
        ),
      ),
      PremisePattern(
        statement_type=(
          TodaPi32WhiteheadSquareUpToSignStatement
        ),
      ),
    ),
    conclusion_builder=build_conclusion,
    match_guard=guard,
  )

def toda_pi4_3_exactness_delta_image_to_suspension_kernel_inference_rule():
  def guard(
    premises,
    bindings,
  ):
    delta_image = (
      premises[
        0
      ].conclusion
    )

    exactness = (
      premises[
        1
      ].conclusion
    )

    window = exactness.window

    if (
      window.first_map
      != EHP_DELTA_MAP
    ):
      return False

    if (
      window.second_map
      != EHP_E_MAP
    ):
      return False

    if (
      delta_image.map.source_group
      != window.source_term
    ):
      return False

    if (
      delta_image.map.target_group
      != window.middle_term
    ):
      return False

    expected_source = TodaPrimaryGroup(
      group_dimension=5,
      sphere_dimension=5,
    )

    expected_middle = TodaPrimaryGroup(
      group_dimension=3,
      sphere_dimension=2,
    )

    expected_target = TodaPrimaryGroup(
      group_dimension=4,
      sphere_dimension=3,
    )

    return (
      window.source_term
      == expected_source
      and window.middle_term
      == expected_middle
      and window.target_term
      == expected_target
    )

  def build_conclusion(
    premises,
  ):
    delta_image = (
      premises[
        0
      ].conclusion
    )

    exactness = (
      premises[
        1
      ].conclusion
    )

    window = exactness.window

    suspension_map = TodaSuspensionMap(
      source_group=window.middle_term,
      target_group=window.target_term,
    )

    return (
      TodaSuspensionKernelFreeCyclicStatement(
        map=suspension_map,
        kernel_group=(
          delta_image.image_group
        ),
      )
    )

  return InferenceRule(
    name=(
      "Toda pi_4^3 exactness "
      "Delta image equals E kernel"
    ),
    description=(
      "For the specific Delta-E exact "
      "window pi_5^5 to pi_3^2 to "
      "pi_4^3, exactness identifies "
      "the image of Delta with the "
      "kernel of the corresponding "
      "suspension map."
    ),
    premise_patterns=(
      PremisePattern(
        statement_type=(
          TodaDeltaImageFreeCyclicStatement
        ),
      ),
      PremisePattern(
        statement_type=(
          TodaProp42ExactnessStatement
        ),
      ),
    ),
    conclusion_builder=build_conclusion,
    match_guard=guard,
  )

def toda_pi4_3_zero_right_implies_suspension_surjective_inference_rule():
  def guard(
    premises,
    bindings,
  ):
    zero_statement = (
      premises[
        0
      ].conclusion
    )

    exactness = (
      premises[
        1
      ].conclusion
    )

    window = exactness.window

    if (
      window.first_map
      != EHP_E_MAP
    ):
      return False

    if (
      window.second_map
      != EHP_H_MAP
    ):
      return False

    if (
      zero_statement.group
      != window.target_term
    ):
      return False

    expected_source = TodaPrimaryGroup(
      group_dimension=3,
      sphere_dimension=2,
    )

    expected_middle = TodaPrimaryGroup(
      group_dimension=4,
      sphere_dimension=3,
    )

    expected_target = TodaPrimaryGroup(
      group_dimension=4,
      sphere_dimension=5,
    )

    return (
      window.source_term
      == expected_source
      and window.middle_term
      == expected_middle
      and window.target_term
      == expected_target
    )

  def build_conclusion(
    premises,
  ):
    exactness = (
      premises[
        1
      ].conclusion
    )

    window = exactness.window

    return (
      TodaSuspensionSurjectiveStatement(
        map=TodaSuspensionMap(
          source_group=window.source_term,
          target_group=window.middle_term,
        ),
      )
    )

  return InferenceRule(
    name=(
      "Toda pi_4^3 E-H exactness "
      "zero-right suspension surjectivity"
    ),
    description=(
      "If the specific E-H window "
      "pi_3^2 to pi_4^3 to pi_4^5 "
      "is exact and pi_4^5 is zero, "
      "then the corresponding "
      "suspension map E from pi_3^2 "
      "to pi_4^3 is surjective."
    ),
    premise_patterns=(
      PremisePattern(
        statement_type=(
          TodaPrimaryGroupZeroStatement
        ),
      ),
      PremisePattern(
        statement_type=(
          TodaProp42ExactnessStatement
        ),
      ),
    ),
    conclusion_builder=build_conclusion,
    match_guard=guard,
  )

def toda_pi4_3_finite_cyclic_inference_rule():
  def guard(
    premises,
    bindings,
  ):
    source_group_relation = (
      premises[
        0
      ].conclusion
    )

    kernel_statement = (
      premises[
        1
      ].conclusion
    )

    surjectivity = (
      premises[
        2
      ].conclusion
    )

    expected_source = TodaPrimaryGroup(
      group_dimension=3,
      sphere_dimension=2,
    )

    expected_target = TodaPrimaryGroup(
      group_dimension=4,
      sphere_dimension=3,
    )

    if (
      source_group_relation.lhs
      != expected_source
    ):
      return False

    if not isinstance(
      source_group_relation.rhs,
      FreeCyclicGroup,
    ):
      return False

    eta_2 = HomotopyElement(
      name="η₂",
      dimension=2,
      source=3,
      target=2,
      generator=GeneratorSymbol(
        family="η",
        index=2,
      ),
    )

    if (
      source_group_relation.rhs.generator
      != eta_2
    ):
      return False

    suspension_map = (
      kernel_statement.map
    )

    if (
      surjectivity.map
      != suspension_map
    ):
      return False

    if (
      suspension_map.source_group
      != expected_source
    ):
      return False

    if (
      suspension_map.target_group
      != expected_target
    ):
      return False

    expected_kernel = FreeCyclicGroup(
      generator=Multiple(
        coefficient=2,
        expression=eta_2,
      ),
    )

    return (
      kernel_statement.kernel_group
      == expected_kernel
    )

  def build_conclusion(
    premises,
  ):
    source_group_relation = (
      premises[
        0
      ].conclusion
    )

    kernel_statement = (
      premises[
        1
      ].conclusion
    )

    eta_2 = (
      source_group_relation
      .rhs
      .generator
    )

    target_group = (
      kernel_statement
      .map
      .target_group
    )

    return Relation(
      lhs=target_group,
      rhs=FiniteCyclicGroup(
        order=2,
        generator=Suspension(
          expression=eta_2,
        ),
      ),
      relation_type=RelationType.EQUALITY,
    )

  return InferenceRule(
    name=(
      "Toda pi_4^3 finite cyclic "
      "quotient calculation"
    ),
    description=(
      "If pi_3^2 is freely generated "
      "by eta_2, the kernel of the "
      "specific suspension map "
      "E: pi_3^2 -> pi_4^3 is freely "
      "generated by 2 eta_2, and that "
      "suspension map is surjective, "
      "then pi_4^3 is the cyclic group "
      "of order 2 generated by E eta_2."
    ),
    premise_patterns=(
      PremisePattern(
        statement_type=Relation,
        relation_type=(
          RelationType.EQUALITY
        ),
      ),
      PremisePattern(
        statement_type=(
          TodaSuspensionKernelFreeCyclicStatement
        ),
      ),
      PremisePattern(
        statement_type=(
          TodaSuspensionSurjectiveStatement
        ),
      ),
    ),
    conclusion_builder=build_conclusion,
    match_guard=guard,
  )

def toda_pi4_3_eta3_generator_inference_rule():
  def guard(
    premises,
    bindings,
  ):
    group_relation = (
      premises[
        0
      ].conclusion
    )

    eta_relation = (
      premises[
        1
      ].conclusion
    )

    expected_group = TodaPrimaryGroup(
      group_dimension=4,
      sphere_dimension=3,
    )

    if (
      group_relation.lhs
      != expected_group
    ):
      return False

    if not isinstance(
      group_relation.rhs,
      FiniteCyclicGroup,
    ):
      return False

    if (
      group_relation.rhs.order
      != 2
    ):
      return False

    eta_2 = HomotopyElement(
      name="η₂",
      dimension=2,
      source=3,
      target=2,
      generator=GeneratorSymbol(
        family="η",
        index=2,
      ),
    )

    eta_3 = HomotopyElement(
      name="η₃",
      dimension=3,
      source=4,
      target=3,
      generator=GeneratorSymbol(
        family="η",
        index=3,
      ),
    )

    expected_suspension = Suspension(
      expression=eta_2,
    )

    if (
      group_relation.rhs.generator
      != expected_suspension
    ):
      return False

    return (
      eta_relation.lhs
      == eta_3
      and eta_relation.rhs
      == expected_suspension
    )

  def build_conclusion(
    premises,
  ):
    group_relation = (
      premises[
        0
      ].conclusion
    )

    eta_relation = (
      premises[
        1
      ].conclusion
    )

    return Relation(
      lhs=group_relation.lhs,
      rhs=FiniteCyclicGroup(
        order=2,
        generator=eta_relation.lhs,
      ),
      relation_type=RelationType.EQUALITY,
    )

  return InferenceRule(
    name=(
      "Toda pi_4^3 eta_3 "
      "generator notation"
    ),
    description=(
      "If pi_4^3 is cyclic of "
      "order 2 generated by E eta_2 "
      "and eta_3 is defined as "
      "E eta_2, then pi_4^3 is "
      "cyclic of order 2 generated "
      "by eta_3."
    ),
    premise_patterns=(
      PremisePattern(
        statement_type=Relation,
        relation_type=(
          RelationType.EQUALITY
        ),
      ),
      PremisePattern(
        statement_type=Relation,
        relation_type=(
          RelationType.EQUALITY
        ),
      ),
    ),
    conclusion_builder=build_conclusion,
    match_guard=guard,
  )
